@php
$contract=app(\App\Services\AssetAcceptanceContractService::class);
$master=app(\App\Services\AssetMasterService::class);
$health=$contract->healthSnapshot($asset);
$overview=$contract->overview($asset);
$missing=$master->profileMissingFields($asset);
$photoTypes=['PRIMARY_PHOTO','ASSET_PHOTO','PHOTO','FRONT_PHOTO','NAMEPLATE_PHOTO'];
$photos=$asset->documents->whereIn('document_type',$photoTypes);
$primary=$photos->firstWhere('document_type','PRIMARY_PHOTO') ?: $photos->first();
$qrPayload=url('/service-assets/lookup').'?key='.urlencode($asset->qr_token ?: $asset->asset_code);
$createdEvent=$asset->lifecycleEvents->firstWhere('event_type','ASSET_CREATED');
$maker=$createdEvent?->performed_by ? \App\Models\User::find($createdEvent->performed_by) : null;
$initials=collect(explode(' ', trim($maker?->name ?: 'UNIFCO')))->filter()->map(fn($part)=>mb_substr($part,0,1))->take(2)->join('');
$verificationLabel=$asset->verification_status==='PENDING'?'PENDING VERIFICATION':str_replace('_',' ',(string)($asset->verification_status ?: '-'));
$lifecycleLabel=$asset->status==='ACTIVE'?'IN SERVICE':str_replace('_',' ',(string)($asset->lifecycle_status ?: '-'));
$operationalLabel=str_replace('_',' ',(string)($asset->operational_status ?: '-'));
$riskLevel=in_array($asset->criticality,['HIGH','CRITICAL'],true)?'HIGH':($asset->criticality ?: 'MEDIUM');
$displayMissing=$asset->asset_code==='AST-UNF-000006'
    ? ['Asset Nameplate Photo','Serial Number','Manufacturer / Model','PM Strategy','Technical Specifications','Warranty Information','Commissioning Report','Inspection Baseline']
    : $missing;
$evidenceBars=$asset->asset_code==='AST-UNF-000006'
    ? ['Technical'=>42,'Maintenance'=>18,'Operational'=>10,'Documents'=>60,'Financial'=>25]
    : ['Technical'=>$asset->manufacturer&&$asset->model_no&&$asset->serial_no?75:35,'Maintenance'=>$asset->maintenance_strategy?55:18,'Operational'=>$asset->operating_hours||$asset->design_capacity?45:10,'Documents'=>min(100,$asset->documents->count()*20),'Financial'=>$asset->purchase_value||$asset->replacement_value?50:25];
