<script>document.addEventListener('DOMContentLoaded',()=>{const bs=[...document.querySelectorAll('#a360tabs [data-tab]')],ps=[...document.querySelectorAll('.a360 .pane')];const open=n=>{bs.forEach(b=>b.classList.toggle('active',b.dataset.tab===n));ps.forEach(p=>p.classList.toggle('active',p.id==='tab-'+n));history.replaceState(null,'','#'+n)};bs.forEach(b=>b.onclick=()=>open(b.dataset.tab));document.querySelectorAll('[data-tab-open]').forEach(b=>b.onclick=()=>open(b.dataset.tabOpen));const h=location.hash.slice(1);open(bs.some(b=>b.dataset.tab===h)?h:'overview')});</script>
